        l = int(next(it)); r = int(next(it))
        A = isqrt(r)
        B = isqrt(l - 1) if l > 0 else 0
        cntA = bisect_right(primes, A)
        cntB = bisect_right(primes, B)
        out_lines.append(str(cntA - cntB))
    sys.stdout.write("\n".join(out_lines))

